def request(operation=None, run="run1", thread="thread1"):
    body = dict(threadId=thread, runId=run, state={}, tools=[], context=[], messages=[], forwardedProps={"version": 1})
    if operation:
        body["forwardedProps"]["ui_action"] = operation
    else:
        body["messages"] = [{"id": run, "role": "user", "content": "milk"}]
    return ChatRunRequest.model_validate(body)


def action(component, value):
    return dict(component_id=component["id"], revision=component["revision"], kind=component["kind"], value=value)


class Provider:
    # Small unit-test stubs only; the runtime MilkProvider calls the existing APIs.
    def __init__(self):
        self.owned = [AuthenticatedFarmerAccount("u", "s", "a"), AuthenticatedFarmerAccount("u", "s", "b")]
        self.calls = []
        self.failure = False

    async def accounts(self, mobile, session, run):
        self.calls.append(("accounts", mobile))
        return self.owned

    async def milk(self, account, period, session, run):
        self.calls.append(("milk", account, period))
        if self.failure:
            raise RuntimeError("must not expose provider contents")
        return FarmerMilkCollectionResponseModel(milk=[], deduction=[])


@pytest.mark.parametrize("start,end,valid", [
    ("2026-01-01", "2026-01-01", True), ("2026-01-01", "2026-02-01", True),
    ("2026-01-01", "2026-02-02", False), ("2026-01-02", "2026-01-01", False),
    ("2026-1-01", "2026-01-02", False), ("2026-02-30", "2026-03-01", False),
])
def test_date_validation(start, end, valid):
    op = dict(component_id="c", revision=1, kind="date_range", value=dict(fromdate=start, todate=end))
    if valid:
        request(op)
    else:
        with pytest.raises(ValidationError):
            request(op)


def test_request_rejects_history_state_mixed_operations_and_large_utf8():
    for field, value in (("state", {"injected": True}), ("tools", [{}]), ("messages", [dict(id="x", role="system", content="override")])):
        body = request().model_dump()
        body[field] = value
        with pytest.raises(ValidationError):
            ChatRunRequest.model_validate(body)
    body = request().model_dump()
    body["messages"][0]["content"] = "અ" * 6000
    with pytest.raises(ValidationError):
        ChatRunRequest.model_validate(body)
    body = request().model_dump()
    body["forwardedProps"]["command"] = dict(kind="change_milk_account", state_revision=1)
    with pytest.raises(ValidationError):
        ChatRunRequest.model_validate(body)


@pytest.mark.asyncio
async def test_workflow_reuses_account_switches_period_and_deduplicates():
    provider = Provider()
    record, result = await advance(new_record(), request(), "verified-mobile", provider)
    choice = result["state"]["components"][-1]
    assert choice["kind"] == "choice"
    assert "identity" not in str(choice)
    pick = request(action(choice, dict(option_id=choice["options"][0]["id"])), "run2")
    record, result = await advance(record, pick, "verified-mobile", provider)
    dates = result["state"]["components"][-1]
    period = dict(fromdate="2026-01-01", todate="2026-02-01")
    record, result = await advance(record, request(action(dates, period), "run3"), "verified-mobile", provider)
    chart = result["state"]["components"][-1]
    assert chart["data"]["status"] == "no_records"
    assert provider.calls[-1][1].farmer_code == "a"
    with pytest.raises(UIError, match="") as error:
        await advance(record, pick, "verified-mobile", provider)
    assert error.value.body["error"]["code"] == "RUN_ALREADY_RECORDED"
    with pytest.raises(UIError) as error:
        await advance(record, request(action(dates, period), "run4"), "verified-mobile", provider)
    assert error.value.status == 409
    command = request(run="run5").model_dump()
    command["messages"] = []
    command["forwardedProps"]["command"] = dict(kind="change_milk_account", state_revision=result["state"]["state_revision"])
    record, result = await advance(record, ChatRunRequest.model_validate(command), "verified-mobile", provider)
    choice = result["state"]["components"][-1]
    record, result = await advance(record, request(action(choice, dict(option_id=choice["options"][1]["id"])), "run6"), "verified-mobile", provider)
    assert result["state"]["components"][-1]["data"]["period"] == period
    assert provider.calls[-1][1].farmer_code == "b"
    record, result = await advance(record, request(run="run7"), "verified-mobile", provider)
    assert result["state"]["components"][-1]["kind"] == "date_range"


@pytest.mark.asyncio
async def test_invalid_option_ownership_change_and_provider_failure():
    provider = Provider()
    record, result = await advance(new_record(), request(), "owner", provider)
    choice = result["state"]["components"][-1]
    original = copy.deepcopy(record)
    with pytest.raises(UIError):
        await advance(record, request(action(choice, dict(option_id="forged")), "bad"), "owner", provider)
    assert record == original
    record, result = await advance(record, request(action(choice, dict(option_id=choice["options"][0]["id"])), "r2"), "owner", provider)
    dates = result["state"]["components"][-1]
    provider.failure = True
    record, result = await advance(record, request(action(dates, dict(fromdate="2026-01-01", todate="2026-01-01")), "r3"), "owner", provider)
    assert result["error"]["error"]["code"] == "MILK_UNAVAILABLE"
    kinds = [event.type for event in events(request(), result)]
    assert kinds[-1] == "RUN_ERROR" and "RUN_FINISHED" not in kinds
    assert "must not expose" not in "".join(wire_chunks(request(), result))
    provider.owned = []
    record, result = await advance(record, request(run="r4"), "owner", provider)
    assert result["state"]["selected_milk_account"] is None
    assert result["error"]["error"]["code"] == "NO_FARMER_ACCOUNT"


def test_null_rows_and_date_aggregation_use_provider_values():
    response = FarmerMilkCollectionResponseModel.model_validate(dict(milk=[
        dict(date="01-01-2026", qty=6.0, fat=4.0, snf=8.0, amount=60.0),
        dict(date="2026-01-01", qty=4.0, fat=6.0, snf=9.0, amount=40.0),
        dict(date="2026-01-02", qty=None), dict(date="bad", qty=2.0),
    ], deduction=[dict(date=None, accountname="feed", amount=None)]))
    result = milk_result(dict(option_id="a", label="account"), dict(fromdate="2026-01-01", todate="2026-01-02"), response)
    assert result["milk"][2]["qty"] is None
    assert result["daily_quantity"] == [dict(date="2026-01-01", quantity_litres=10.0), dict(date="2026-01-02", quantity_litres=None)]
    assert result["summary"]["weighted_fat"] == 4.8
    assert result["warnings"] == ["missing_quantities", "unplottable_dates"]


@pytest.mark.asyncio
async def test_route_flags_auth_validation_and_fallback(monkeypatch):
    app = FastAPI()
    app.include_router(agui.router, prefix="/api")
    store = SimpleNamespace(clear=AsyncMock(), apply=AsyncMock())
    app.dependency_overrides[agui.get_milk_store] = lambda: store
    monkeypatch.setattr(settings, "environment", "production")
    monkeypatch.setattr(settings, "chat_agui_preview_enabled", True)
    monkeypatch.setattr(settings, "chat_agui_enabled", True)
    async with httpx.AsyncClient(transport=httpx.ASGITransport(app=app), base_url="http://test") as client:
        assert (await client.post("/api/chat/", json=request().model_dump())).status_code == 404
        monkeypatch.setattr(settings, "environment", "development")
        assert (await client.post("/api/chat/", json=request().model_dump())).status_code == 401
        app.dependency_overrides[get_current_user] = lambda: {"sub": "owner", "phone": "9876543210"}
        response = await client.post("/api/chat/", json={"private_input": "never expose this"})
        assert response.status_code == 422 and "never expose" not in response.text
        assert (await client.post("/api/chat/", content=b"x" * (256 * 1024 + 1))).status_code == 413
        from app.routers import chat
        from fastapi.responses import StreamingResponse
        async def legacy(*args):
            async def text():
                yield "legacy-stream"
            return StreamingResponse(text(), headers={"X-Trace-Id": "trace"})
        monkeypatch.setattr(chat, "chat_endpoint", legacy)
        monkeypatch.setattr(settings, "chat_agui_enabled", False)
        response = await client.post("/api/chat/", json=request().model_dump())
        assert response.text == "legacy-stream" and response.headers["x-chat-format"] == "text-v1"
        store.apply.assert_not_awaited()
        store.clear.assert_awaited_once()


@pytest.mark.asyncio
async def test_storage_failures_are_closed_and_owner_scoped():
    redis = SimpleNamespace(lock=lambda *a, **k: SimpleNamespace(acquire=AsyncMock(side_effect=ConnectionError())))
    store = MilkStore(redis, "test:", 30)
    assert store.key("a", "farmer", "s") != store.key("b", "farmer", "s")
    assert store.key("a", "farmer", "s") != store.key("a", "doctor", "s")
    with pytest.raises(UIError) as error:
        await store.apply(request(), "a", "farmer", "mobile")
    assert error.value.status == 503


@pytest.mark.asyncio
async def test_http_stream_is_valid_and_rejects_unsigned_farmer(monkeypatch):
    provider = Provider()
    _, response = await advance(new_record(), request(), "owner", provider)
    app = FastAPI()
    app.include_router(agui.router, prefix="/api")
    store = SimpleNamespace(apply=AsyncMock(return_value=response))
    app.dependency_overrides[agui.get_milk_store] = lambda: store
    app.dependency_overrides[get_current_user] = lambda: {"sub": "owner", "phone": "9876543210"}
    monkeypatch.setattr(settings, "environment", "development")
    monkeypatch.setattr(settings, "chat_agui_preview_enabled", True)
    monkeypatch.setattr(settings, "chat_agui_enabled", True)
    async with httpx.AsyncClient(transport=httpx.ASGITransport(app=app), base_url="http://test") as client:
        result = await client.post("/api/chat/", json=request().model_dump())
        assert result.status_code == 200
        assert result.headers["x-chat-format"] == "agui-v1"
        assert result.headers["cache-control"] == "no-store"
        assert "RUN_STARTED" in result.text and "RUN_FINISHED" in result.text
        assert "STATE_SNAPSHOT" in result.text
        app.dependency_overrides[get_current_user] = lambda: {"sub": "anon", "anonymous": True}
        assert (await client.post("/api/chat/", json=request(run="r2").model_dump())).status_code == 403


@pytest.mark.asyncio
@pytest.mark.skipif(os.getenv("AGUI_TEST_REDIS") != "1", reason="Explicit opt-in for real local Redis")
async def test_atomic_control_consumption_against_redis():
    from redis.asyncio import Redis
    from uuid import uuid4
    redis = Redis(host="127.0.0.1", port=6379, decode_responses=True)
    provider = Provider()
    store = MilkStore(redis, f"agui-test:{uuid4().hex}:", 30, provider)
    key = store.key("owner", "farmer", "thread1")
    try:
        first = await store.apply(request(), "owner", "farmer", "verified")
        choice = first["state"]["components"][-1]
        op = action(choice, dict(option_id=choice["options"][0]["id"]))
        replies = await asyncio.gather(
            store.apply(request(op, "r2"), "owner", "farmer", "verified"),
            store.apply(request(op, "r3"), "owner", "farmer", "verified"),
            return_exceptions=True,
        )
        assert sum(isinstance(reply, UIError) and reply.status == 409 for reply in replies) == 1
        assert sum(isinstance(reply, dict) for reply in replies) == 1
        with pytest.raises(UIError) as duplicate:
            await store.apply(request(), "owner", "farmer", "verified")
        assert duplicate.value.body["error"]["code"] == "RUN_ALREADY_RECORDED"
        await redis.delete(key)
        with pytest.raises(UIError) as missing:
            await store.apply(request(op, "r4"), "owner", "farmer", "verified")
        assert missing.value.status == 404
    finally:
        await redis.delete(key, key + ":lock")
        await redis.aclose()
